SELECT oid, spcname, spcowner::regrole, pg_tablespace_location(oid)
  FROM pg_tablespace;

CREATE ROLE app_owner LOGIN PASSWORD 'Secret#2026';
CREATE DATABASE shopdb OWNER app_owner;
\c shopdb
SET ROLE app_owner;

CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id int NOT NULL,
    order_date  date NOT NULL,
    amount      numeric(10,2) NOT NULL
);

INSERT INTO orders (customer_id, order_date, amount)
SELECT (g % 500) + 1,
       date '2026-01-01' + (g % 300),
       round((g % 997) * 1.37, 2)
  FROM generate_series(1, 50000) g;

SELECT oid, datname FROM pg_database WHERE datname = 'shopdb';
SELECT pg_relation_filepath('orders');

\c shopdb
SET ROLE app_owner;
CREATE TABLE payments (payment_id bigint PRIMARY KEY) TABLESPACE fast_ssd;

RESET ROLE;
GRANT CREATE ON TABLESPACE fast_ssd TO app_owner;
\db+ fast_ssd

SET ROLE app_owner;

CREATE TABLE payments (
    payment_id  bigint PRIMARY KEY USING INDEX TABLESPACE fast_ssd,
    order_id    bigint NOT NULL,
    paid_at     timestamptz NOT NULL
) TABLESPACE fast_ssd;

INSERT INTO payments
SELECT g, g, timestamptz '2026-01-01' + g * interval '1 minute'
  FROM generate_series(1, 20000) g;

CREATE INDEX payments_order_id_idx ON payments (order_id)
    TABLESPACE fast_ssd;

SELECT tablename, tablespace FROM pg_tables
 WHERE schemaname = 'public' ORDER BY tablename;

SELECT indexname, tablespace FROM pg_indexes
 WHERE schemaname = 'public' ORDER BY indexname;

SELECT pg_relation_filepath('payments') AS table_file,
       pg_relation_filepath('payments_pkey') AS pkey_file;

SHOW default_tablespace;
SET default_tablespace = fast_ssd;
CREATE TABLE refunds (refund_id bigint PRIMARY KEY, amount numeric(10,2));

SELECT c.relname, t.spcname
  FROM pg_class c
  LEFT JOIN pg_tablespace t ON t.oid = c.reltablespace
 WHERE c.relname LIKE 'refunds%' ORDER BY 1;
RESET default_tablespace;

SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

ALTER TABLE orders SET TABLESPACE fast_ssd;

SELECT pg_relation_filepath('orders') AS table_file,
       pg_relation_filepath('orders_pkey') AS index_file;

ALTER INDEX orders_pkey SET TABLESPACE fast_ssd;

BEGIN;
ALTER TABLE payments SET TABLESPACE pg_default;
SELECT relation::regclass, mode, granted
  FROM pg_locks
 WHERE pid = pg_backend_pid() AND relation = 'payments'::regclass;
ROLLBACK;

CREATE TABLESPACE archive_hdd LOCATION '/mnt/slow_hdd/pg18';
CREATE DATABASE reportdb OWNER app_owner TABLESPACE archive_hdd;

SELECT d.datname, t.spcname AS default_tablespace
  FROM pg_database d
  JOIN pg_tablespace t ON t.oid = d.dattablespace
 WHERE d.datname IN ('postgres', 'shopdb', 'reportdb')
 ORDER BY 1;

SELECT pg_reload_conf();
SELECT name, setting, context, source
  FROM pg_settings WHERE name = 'temp_tablespaces';

CREATE TEMP TABLE cart_tmp (id int);
